<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response,Validator};use App\Repositories\{EmployeeRepository,SettingsRepository,SupportRepository};use App\Services\CredentialService;use App\Support\{Flash,UploadPolicy};
final class EmployeesController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():EmployeeRepository{return new EmployeeRepository($this->app->database());}private function denied():?Response{return can('employees.view')?null:Response::html('Forbidden',403);}private function fail(string$u,array$e,array$o):Response{$this->app->session()->flash('_errors',$e);$this->app->session()->flash('_old',$o);Flash::add('error',reset($e)[0]??'Please correct the form.');return Response::redirect(url($u));}
public function index(Request$r):Response{if($x=$this->denied())return$x;$q=trim((string)$r->query('employee_search',''));return$this->renderPage('employees',['employees'=>$this->r()->all($this->i(),$q),'search'=>$q]);}public function create(Request$r):Response{if($x=$this->denied())return$x;return$this->renderPage('employee-add',['employee'=>null]);}public function edit(Request$r):Response{if($x=$this->denied())return$x;$e=$this->r()->find((int)$r->route('id'),$this->i());return$e?$this->renderPage('employee-add',['employee'=>$e]):Response::html('Employee not found',404);}public function store(Request$r):Response{return$this->save($r,null);}public function update(Request$r):Response{return$this->save($r,(int)$r->route('id'));}
private function save(Request$r,?int$id):Response{if($x=$this->denied())return$x;$d=$r->all();$v=new Validator();if(!$v->validate($d,['studentname'=>'required|max:160','doa'=>'required|date','class'=>'required|in:Principal,Management Staff,Teacher,Accountant,Store Manager,Other','rollno'=>'required|numeric|min:0','email'=>'email|max:190','dob'=>'date']))return$this->fail($id?'/admin/employees/'.$id.'/edit':'/admin/employees/create',$v->errors(),$d);$old=$id?$this->r()->find($id,$this->i()):null;if($id&&!$old)return Response::html('Employee not found',404);$picture=$this->image($r->file('fileToUpload'));if($picture===false)return$this->fail($id?'/admin/employees/'.$id.'/edit':'/admin/employees/create',['fileToUpload'=>['Picture must be JPG/PNG no larger than 100KB.']],$d);$now=date('Y-m-d H:i:s');$row=['institute_id'=>$this->i(),'employee_no'=>$old['employee_no']??('EMP-'.date('ymdHis').'-'.bin2hex(random_bytes(2))),'name'=>trim((string)$d['studentname']),'picture_path'=>$picture?:($old['picture_path']??null),'mobile'=>trim((string)($d['phone']??''))?:null,'joining_date'=>$d['doa'],'role'=>$d['class'],'monthly_salary'=>(float)$d['rollno'],'show_on_profile'=>(int)isset($d['profile']),'father_husband_name'=>trim((string)($d['fathername']??''))?:null,'national_id'=>trim((string)($d['scnic']??''))?:null,'education'=>trim((string)($d['fcnic']??''))?:null,'gender'=>$d['gender']?:null,'religion'=>$d['religion']?:null,'blood_group'=>$d['blood']?:null,'experience'=>trim((string)($d['health']??''))?:null,'email'=>trim((string)($d['email']??''))?:null,'date_of_birth'=>$d['dob']?:null,'home_address'=>trim((string)($d['address']??''))?:null,'status'=>$old['status']??'active','updated_at'=>$now];if($id){unset($row['institute_id']);$this->r()->update($id,$this->i(),$row);if($picture&&!empty($old['picture_path'])){$p=BASE_PATH.'/public/'.$old['picture_path'];if(is_file($p))unlink($p);}Flash::add('success','Employee updated.');}else{$row['created_at']=$now;$id=$this->r()->create($row);Flash::add('success','Employee created.');}return Response::redirect(url('/admin/employees'));}
private function image(?array$f):string|false|null{if(!$f||($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;$p=new UploadPolicy(['image/jpeg','image/png'],['jpg','jpeg','png'],102400);if(!$p->validate($f))return false;$n=$p->safeFilename(pathinfo((string)$f['name'],PATHINFO_EXTENSION));$d=BASE_PATH.'/public/uploads/employees';if(!is_dir($d))mkdir($d,0775,true);return move_uploaded_file($f['tmp_name'],$d.'/'.$n)?'uploads/employees/'.$n:false;}
public function status(Request$r):Response{if($x=$this->denied())return$x;$e=$this->r()->find((int)$r->route('id'),$this->i());if(!$e)return Response::html('Employee not found',404);$s=(string)$r->input('status');if(!in_array($s,['active','inactive'],true))return Response::html('Invalid status',422);$this->r()->update((int)$e['id'],$this->i(),['status'=>$s,'updated_at'=>date('Y-m-d H:i:s')]);Flash::add('success','Employee status updated.');return Response::redirect(url('/admin/employees'));}public function jobLetter(Request$r):Response{return$this->renderPage('employee-job-letter',['employee'=>$this->r()->find((int)$r->query('employee_id',0),$this->i()),'employees'=>$this->r()->all($this->i()),'institute'=>(new SettingsRepository($this->app->database()))->institute(),'rules'=>(new SettingsRepository($this->app->database()))->rules($this->i())]);}public function logins(Request$r):Response{$accounts=(new SupportRepository($this->app->database()))->accounts('employee',$this->i());$credentials=new CredentialService($this->app->database());foreach($accounts as&$account)$account['visible_password']=$credentials->reveal($account['password_cipher']??null);unset($account);return$this->renderPage('staff-logins',['accounts'=>$accounts,'temporaryCredential'=>$this->app->session()->pull('temporary_credential')]);}public function createLogin(Request$r):Response{try{$result=(new CredentialService($this->app->database()))->create('employee',(int)$r->input('employee_id'),$this->i(),(string)$r->input('email'),(int)user()['id'],trim((string)$r->input('password'))?:null);}catch(\Throwable$e){Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/employees/logins'));}$this->app->session()->flash('temporary_credential',$result['temporary_password']);return Response::redirect(url('/admin/employees/logins'));}
}
